  }

  const message = boundedString(value["message"]);
  const documentationUrl = boundedString(value["documentation_url"]);

  return {
    ...headerDiagnostics,
    ...(message === undefined ? {} : { message }),
    ...(documentationUrl === undefined ? {} : { documentationUrl }),
  };
