      ).toBe(400);
      expect(fetch).toHaveBeenCalledTimes(1);
    },
  );

  it.each(["/token/", "/tokenized", "/github/apps/example-app/token"])(
    "does not forward %s",
    async (path) => {
      const fetch = vi.fn();
      expect(
        (
