      expect(fetch).not.toHaveBeenCalled();
    },
  );

  it.each([
    undefined,
    "http://broker.example/github/apps/a/token",
    "REDACTED",
    "https://broker.example/token",
    `${endpoint}?app=other`,
    `${endpoint}#fragment`,
  ])("rejects invalid deployment endpoint %s before I/O", async (url) => {
    const fetch = vi.fn();
