  });

  it.each([undefined, "not a URL"])(
    "isolates missing or invalid endpoint %s from root and fallback",
    async (TOKEN_PROXY_ENDPOINT) => {
      const fetch = vi.fn();
      for (const [path, method, status] of [
        ["/", "GET", 200],
        ["/", "HEAD", 200],
        ["/", "POST", 405],
        ["/token/", "POST", 404],
        ["/absent", "GET", 404],
      ] as const) {
        const response = await invoke(new Request(`https://vanity.example${path}`, { method }), {
          fetch,
