r.forEach((result,i)=>{if(result.status==="fulfilled"){store("pr_jobs_"+i,result.value);text({name:specs[i].name,data:result.value.structuredContent ?? result.value});}else text({i,error:String(result.reason)});});

for(let i=0;i<5;i++){
const jobs=load("pr_jobs_"+i).structuredContent.jobs;
text({pr:load("pr_created_"+i).structuredContent.number,jobs:jobs.map(j=>({name:j.name,status:j.status,conclusion:j.conclusion}))});
}

