const result=await tools.mcp__codex_apps__github_fetch_commit_workflow_runs({repo_full_name:"chikachow/cyspbot",commit_sha:load("pr_specs")[i].sha});
store("pr_runs_"+i,result);return {pr:load("pr_created_"+i).structuredContent.number,runs:result.structuredContent};
}));results.forEach(text);

