 ]);
 store("pr_final_"+i,pr);store("pr_status_"+i,status);
 const p=pr.structuredContent;
 return {name:s.name,pr:p?{number:p.number,url:p.url,draft:p.draft,base:p.base,head_sha:p.head_sha,mergeable:p.mergeable}:pr,status:status.structuredContent??status};
}));results.forEach(text);

