 const s=load("pr_specs")[i];
 if(p.head_sha!==s.sha || p.draft!==true || p.base!=="main")throw new Error("Unexpected PR state for "+s.name);
 text({number:p.number,draft:p.draft,head:p.head_sha,base:p.base,base_sha:p.base_sha,mergeable:p.mergeable,comments:load("pr_final_"+i).structuredContent.comments});
}
